import { test, expect, Page } from '@playwright/test';

test.describe('Polling stops when navigating away from page', () => {
  let page: Page;
  let pollRequestCount = 0;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    pollRequestCount = 0;

    // Intercept polling requests to track them
    await page.route('**/api/poll', (route) => {
      pollRequestCount++;
      route.continue();
    });

    await page.goto('http://localhost:3000/polling-page');
  });

  test('should stop polling when navigating to a different page', async () => {
    // Wait for initial polling to start
    await page.waitForTimeout(1000);
    const initialPollCount = pollRequestCount;
    expect(initialPollCount).toBeGreaterThan(0);

    // Navigate away from the page
    await page.goto('http://localhost:3000/other-page');

    // Record poll count after navigation
    const pollCountAfterNavigation = pollRequestCount;

    // Wait to ensure no additional polls are made
    await page.waitForTimeout(2000);
    const finalPollCount = pollRequestCount;

    // Verify that no new polls were made after navigation
    expect(finalPollCount).toBe(pollCountAfterNavigation);
  });

  test('should stop polling when closing the page', async () => {
    // Wait for polling to establish
    await page.waitForTimeout(1000);
    const initialPollCount = pollRequestCount;
    expect(initialPollCount).toBeGreaterThan(0);

    // Record the poll count before closing
    const pollCountBeforeClose = pollRequestCount;

    // Close the page
    await page.close();

    // Create a new page to verify the old one is truly closed
    const newPage = await page.context().newPage();
    await newPage.goto('http://localhost:3000/polling-page');

    // Wait a bit and verify the old page's poll count hasn't increased
    await newPage.waitForTimeout(1000);

    // The original page should have stopped polling
    expect(pollRequestCount).toBe(pollCountBeforeClose);

    await newPage.close();
  });

  test('should continue polling when staying on the same page', async () => {
    // Wait for initial polling
    await page.waitForTimeout(1000);
    const initialPollCount = pollRequestCount;
    expect(initialPollCount).toBeGreaterThan(0);

    // Interact with the page but don't navigate away
    const button = page.getByRole('button', { name: /refresh/i });
    if (await button.isVisible()) {
      await button.click();
    }

    // Wait for more polling to occur
    await page.waitForTimeout(2000);
    const finalPollCount = pollRequestCount;

    // Verify that polling continued
    expect(finalPollCount).toBeGreaterThan(initialPollCount);
  });

  test('should stop polling when navigating back using browser back button', async () => {
    // Navigate to a different page first
    await page.goto('http://localhost:3000/other-page');
    await page.waitForTimeout(500);

    // Navigate back to polling page
    await page.goto('http://localhost:3000/polling-page');
    await page.waitForTimeout(1000);
    const pollCountBeforeBack = pollRequestCount;

    // Navigate away again
    await page.goto('http://localhost:3000/other-page');
    await page.waitForTimeout(500);

    // Use browser back button
    await page.goBack();
    await page.waitForTimeout(1000);

    // Navigate away from polling page
    await page.goto('http://localhost:3000/another-page');
    const pollCountAfterSecondNavigation = pollRequestCount;

    // Wait to ensure no additional polls
    await page.waitForTimeout(2000);
    const finalPollCount = pollRequestCount;

    // Verify polling stopped after final navigation
    expect(finalPollCount).toBe(pollCountAfterSecondNavigation);
  });

  test('should verify polling status indicator updates when navigating away', async () => {
    // Check if polling status is visible
    const statusIndicator = page.getByText(/polling.*active/i);

    if (await statusIndicator.isVisible()) {
      expect(await statusIndicator.isVisible()).toBe(true);

      // Navigate away
      await page.goto('http://localhost:3000/other-page');

      // Verify status indicator is no longer visible or shows inactive
      const inactiveStatus = page.getByText(/polling.*inactive/i);
      const isInactive = await inactiveStatus.isVisible().catch(() => false);

      // Either the active indicator should be gone or inactive indicator should appear
      const activeStillVisible = await statusIndicator.isVisible().catch(() => false);
      expect(activeStillVisible || isInactive).toBe(true);
    }
  });
});
